from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import base64,zipfile,hashlib
R=Path('/home/user/chantier-corrections-bassin-53-54')
labels=[('ombre-falaise-est','Rebord de falaise à droite'),('ombre-falaise-gauche-haut','Rebord sous un arbre — haut'),('ombre-falaise-gauche-milieu','Rebord sous des arbres — milieu'),('ombre-falaise-gauche-bas','Rebord sous un arbre — bas'),('arbre-est','Arbre à l’est de la cascade'),('arbre-sud','Arbre près du chemin sud'),('eau','Trait isolé dans l’eau')]
images=[]
for key,label in labels:
 a=Image.open(R/(key+'-avant.png')).convert('RGB');b=Image.open(R/(key+'-apres.png')).convert('RGB');assert a.size==b.size
 width=max(a.width,350);panel=Image.new('RGB',(width*2+16,a.height+58),'#f7f7f2');panel.paste(a,(0,58));panel.paste(b,(width+16,58));d=ImageDraw.Draw(panel);font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',17);d.text((4,3),label,font=font,fill='#163b32');d.text((4,32),'AVANT',font=font,fill='#783626');d.text((width+20,32),'APRÈS · CANDIDAT LOCAL',font=font,fill='#17724f');p=R/('comparaison-'+key+'.png');panel.save(p);images.append((label,p))
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
full=data(R/'apres-candidat.png');cards=''.join('<article><h3>'+label+'</h3><img src="'+data(path)+'" alt="Comparaison avant après : '+label+'"></article>' for label,path in images)
html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Corrections locales du bassin de Réverie</title><style>body{margin:0;background:#eff5ed;color:#17392e;font:16px/1.55 system-ui}header{padding:36px max(20px,5vw);background:#173d34;color:#f6fff4}h1{font-size:clamp(28px,4vw,48px);line-height:1.1;margin:6px 0}header p{color:#c7ddca}main{max-width:1280px;margin:auto;padding:24px}section,article{background:white;border:1px solid #d0dfd0;border-radius:12px;margin:14px 0;padding:18px}img{display:block;max-width:100%;height:auto;image-rendering:pixelated;margin:auto}.warn{background:#fff1ce;border-left:4px solid #b47810;padding:15px}.muted{color:#516b5d}a{color:#066c4c}h3{margin:0 0 10px}</style><header><small>DESTINY · CHANTIER LOCAL</small><h1>Bassin de Réverie</h1><p>Rebords dégagés, pieds d’arbres restaurés et trait isolé dans l’eau : avant / après.</p></header><main><div class="warn"><b>Corrections locales, pas encore installées ni testées en jeu.</b> Ces images sont des rendus statiques des données. Les rives hautes, les chemins et la touffe repérés auparavant restent à reprendre ; les corrections ne constituent pas un audit exhaustif.</div><section><h2>Vue d’ensemble — candidat local</h2><p>La carte, ses collisions et ses personnages restent en place. Le doyen et son animation ne sont pas ajoutés par ce correctif.</p><img src="'''+full+'''" alt="Vue d’ensemble du bassin, candidat local"></section><section><h2>Comparaisons détaillées</h2><p class="muted">Pour les ombres, les pixels de falaise recouvrent seulement les pixels identifiés comme ombre. Pour les arbres, les pieds proviennent d’un arbre complet identique. Dans l’eau, seule la cellule du trait isolé a été retirée.</p>'''+cards+'''</section><section><h2>Ce qui reste à vérifier</h2><p>Raccords de rive 1G/1D, chemins est et sud, petite touffe ; vérification dans l’éditeur PMDO, de toutes les animations et d’une ancienne sauvegarde. <a href="ETAT-CORRECTIONS-53-54.md">Voir le compte rendu</a>. Aucun push, release ni CI.</p></section></main></html>'''
(R/'apercu-corrections-bassin.html').write_text(html,encoding='utf8')
# Keep the deliverable compact and self-contained, but never present it as a tested release.
archive=R/'candidat-corrections-bassin-53-54.zip';files=[R/'ETAT-CORRECTIONS-53-54.md',R/'RAPPORT-PREALABLE.md',R/'original-jeu.rsground.gz',R/'original-dev.rsground.gz',R/'journal-corrections.json',R/'candidat/payload/reverie_etang.rsground.gz',R/'candidat/payload/reverie_etang_Dev.rsground.gz',R/'banques/Reverie_Correction_Ombres_5354.tile',R/'verifier-candidat.py',R/'apercu-corrections-bassin.html']
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
 for p in files:z.write(p,p.relative_to(R))
with zipfile.ZipFile(archive) as z:assert z.testzip() is None
print('Aperçu comparatif et archive CRC OK',archive.stat().st_size,hashlib.sha256(archive.read_bytes()).hexdigest())
